package main

import (
	"context"
	"fmt"
	"log"
	"os"
	"strings"

	"github.com/segmentio/kafka-go"
	"google.golang.org/grpc"
	"google.golang.org/grpc/metadata"
)

type StreamProcessor struct {
	reader     *kafka.Reader
	grpcConn   *grpc.ClientConn
	outputTopic string
}

func NewStreamProcessor(brokers []string, topic, groupID, grpcTarget string) (*StreamProcessor, error) {
	reader := kafka.NewReader(kafka.ReaderConfig{
		Brokers:  brokers,
		Topic:    topic,
		GroupID:  groupID,
		MinBytes: 10e3,
		MaxBytes: 10e6,
	})

	conn, err := grpc.Dial(grpcTarget, grpc.WithInsecure())
	if err != nil {
		return nil, fmt.Errorf("failed to connect to gRPC: %w", err)
	}

	return &StreamProcessor{
		reader:   reader,
		grpcConn: conn,
	}, nil
}

// ProcessMessages reads from Kafka and forwards enriched data via gRPC
func (sp *StreamProcessor) ProcessMessages(ctx context.Context) error {
	for {
		msg, err := sp.reader.ReadMessage(ctx)
		if err != nil {
			if ctx.Err() != nil {
				return nil
			}
			log.Printf("error reading message: %v", err)
			continue
		}

		// Extract headers from Kafka message and forward as gRPC metadata
		// This enables end-to-end tracing and tenant routing
		md := metadata.New(nil)
		for _, header := range msg.Headers {
			// Forward all Kafka headers as gRPC metadata pairs
			// Headers prefixed with x-route- control downstream routing
			md.Append(header.Key, string(header.Value))
		}

		// Add processing metadata
		md.Append("x-source-partition", fmt.Sprintf("%d", msg.Partition))
		md.Append("x-source-offset", fmt.Sprintf("%d", msg.Offset))

		// The service account token is read from the mounted volume
		// In production, this is the projected service account token
		tokenPath := os.Getenv("SA_TOKEN_PATH")
		if tokenPath == "" {
			tokenPath = "/var/run/secrets/kubernetes.io/serviceaccount/token"
		}
		token, err := os.ReadFile(tokenPath)
		if err != nil {
			log.Printf("warning: could not read SA token: %v", err)
		} else {
			md.Append("authorization", "Bearer "+strings.TrimSpace(string(token)))
		}

		// Create outgoing context with metadata from Kafka headers
		outCtx := metadata.NewOutgoingContext(ctx, md)

		// Forward to downstream gRPC service
		err = sp.forwardToDownstream(outCtx, msg.Value)
		if err != nil {
			log.Printf("error forwarding message: %v", err)
		}
	}
}

func (sp *StreamProcessor) forwardToDownstream(ctx context.Context, payload []byte) error {
	// In real implementation, this calls a specific gRPC service method
	// The metadata from ctx is automatically sent with the RPC call
	stream, err := sp.grpcConn.NewStream(ctx, &grpc.StreamDesc{
		StreamName:    "ProcessEvent",
		ServerStreams: false,
		ClientStreams: false,
	}, "/eventprocessor.v1.EventProcessor/ProcessEvent")
	if err != nil {
		return err
	}
	return stream.SendMsg(payload)
}

func main() {
	brokers := strings.Split(os.Getenv("KAFKA_BROKERS"), ",")
	topic := os.Getenv("KAFKA_TOPIC")
	groupID := os.Getenv("KAFKA_GROUP_ID")
	grpcTarget := os.Getenv("GRPC_TARGET")

	if len(brokers) == 0 || topic == "" || grpcTarget == "" {
		log.Fatal("KAFKA_BROKERS, KAFKA_TOPIC, and GRPC_TARGET must be set")
	}
	if groupID == "" {
		groupID = "stream-processor"
	}

	processor, err := NewStreamProcessor(brokers, topic, groupID, grpcTarget)
	if err != nil {
		log.Fatalf("failed to create processor: %v", err)
	}

	log.Printf("Starting stream processor: topic=%s group=%s target=%s", topic, groupID, grpcTarget)
	if err := processor.ProcessMessages(context.Background()); err != nil {
		log.Fatalf("processor error: %v", err)
	}
}
